 <span role="columnheader">Number</span>
 <span role="columnheader">Material / Product</span>
 <span role="columnheader">Type</span>
 <span role="columnheader">Location</span>
 <span role="columnheader">Batch / Lot</span>
 <span role="columnheader">Total Qty</span>
 <span role="columnheader">Reserved Qty</span>
 <span role="columnheader">Available Qty</span>
 <span role="columnheader">Status</span>
 <span role="columnheader">Last Updated</span>
 </div>
 {stockList.map((row, idx) => (
 <div className="inv-table-row" role="row" key={row.sysId || idx}>
 <span className="inv-table-cell inv-stock-number" role="cell">
 <a
 href={`/x_2056099_indust_0_stock_detail.do?sys_id=${row.sysId}`}
 >
 {row.number}
 </a>
 </span>
 <span className="inv-table-cell" role="cell">
 {row.material || "—"}
 </span>
 <span className="inv-table-cell" role="cell">
 {row.inventoryType || "—"}
 </span>
 <span className="inv-table-cell" role="cell">
 {row.location || "—"}
 </span>
 <span className="inv-table-cell" role="cell">
 {row.batchLot || "—"}
 </span>
 <span className="inv-table-cell inv-qty" role="cell">
 {Number(row.totalQty).toLocaleString()}
 </span>
 <span className="inv-table-cell inv-qty" role="cell">
 {Number(row.reservedQty).toLocaleString()}
 </span>
 <span className="inv-table-cell inv-qty" role="cell">
 {Number(row.availableQty).toLocaleString()}
 </span>
 <span
 className={`inv-table-cell ${STATUS_CLASS[row.status] || ""}`}
 role="cell"
 >
 {row.status || "—"}
 </span>
 <span className="inv-table-cell" role="cell">
 {row.lastUpdated || "—"}
 </span>
 </div>
 ))}
 </div>
 </div>
 </section>
 );
}
","export default function insertStyle(css, tagName = "style") {
 if (!css || typeof window === "undefined")
 return;
 if (tagName === "style") {
 const style = document.createElement("style");
 style.setAttribute("type", "text/css");
 style.innerHTML = css;
 document.head.appendChild(style);
 }
 else if (tagName === "link") {
 const link = document.createElement("link");
 link.setAttribute("rel", "stylesheet");
 link.setAttribute("href", css);
 document.head.appendChild(link);
 }
 return css;
}","/* ── Inventory Overview Page ─ Horizon Design Tokens ─────────────────── */

/* Page layout */
.inv-container {
