 color: rgb(var(--now-color_text--primary, 22, 27, 28));
 background: rgb(var(--now-color_background--primary, 255, 255, 255));
 min-height: 100vh;
}

/* Header */
.inv-header {
 margin-bottom: 32px;
 padding-bottom: 20px;
 border-bottom: 1px solid rgb(var(--now-color_divider--tertiary, 220, 224, 226));
}
.inv-title {
 margin: 0 0 6px;
 font-size: 28px;
 font-weight: 600;
 color: rgb(var(--now-color_text--primary, 22, 27, 28));
}
.inv-subtitle {
 margin: 0;
 font-size: 15px;
 color: rgb(var(--now-color_text--secondary, 73, 80, 84));
}

/* Shared section title */
