","import React, { useState, useEffect, useCallback } from "react";
import SummaryCards from "./components/SummaryCards";
import CategoryGrid from "./components/CategoryGrid";
import StockFilters from "./components/StockFilters";
import StockTable from "./components/StockTable";
import "./app.css";

interface FilterOption {
 value: string;
 label: string;
}

interface FilterOptions {
 inventoryTypes: FilterOption[];
 statuses: FilterOption[];
 locations: FilterOption[];
 materials: FilterOption[];
}

interface SummaryData {
 totalRecords: number;
 totalQuantity: number;
 totalReserved: number;
 totalAvailable: number;
}

interface CategoryData {
 value: string;
 label: string;
 count: number;
}

interface StockRecord {
 number: string;
 material: string;
 inventoryType: string;
 location: string;
 batchLot: string;
 totalQty: string;
 reservedQty: string;
 availableQty: string;
 status: string;
 lastUpdated: string;
 sysId: string;
}

interface InventoryData {
 summary: SummaryData;
 categories: CategoryData[];
 stockList: StockRecord[];
 filterOptions: FilterOptions;
}

interface Filters {
 inventoryType: string;
 materialProduct: string;
 location: string;
 status: string;
}

const EMPTY_FILTERS: Filters = {
 inventoryType: "",
 materialProduct: "",
 location: "",
 status: "",
};

const API_BASE = "/api/x_2056099_indust_0/inventory_api/data";

export default function App() {
 const [data, setData] = useState<InventoryData | null>(null);
 const [filters, setFilters] = useState<Filters>(EMPTY_FILTERS);
 const [loading, setLoading] = useState(true);
 const [error, setError] = useState("");

 const fetchData = useCallback((currentFilters: Filters) => {
 setLoading(true);
 setError("");

 const params = new URLSearchParams();
 if (currentFilters.inventoryType)
 params.set("inventory_type", currentFilters.inventoryType);
 if (currentFilters.materialProduct)
 params.set("material_product", currentFilters.materialProduct);
 if (currentFilters.location)
 params.set("location", currentFilters.location);
 if (currentFilters.status) params.set("status", currentFilters.status);

 const qs = params.toString();
 const url = qs ? `${API_BASE}?${qs}` : API_BASE;

 fetch(url, {
 headers: {
 Accept: "application/json",
 "X-UserToken": (window as any).g_ck,
 },
 })
 .then((r) => {
 if (!r.ok) throw new Error(`HTTP ${r.status}`);
 return r.json();
 })
 .then((d) => setData(d.result))
 .catch((e) => setError(e.message))
 .finally(() => setLoading(false));
 }, []);

 useEffect(() => {
 fetchData(EMPTY_FILTERS);
 }, [fetchData]);

 function handleFilterChange(newFilters: Filters) {
 setFilters(newFilters);
 fetchData(newFilters);
 }

 if (loading && !data)
 return <div className="inv-loading">Loading inventory data…</div>;
 if (error && !data)
 return <div className="inv-error">Error: {error}</div>;

 return (
 <div className="inv-container">
 <header className="inv-header">
 <h1 className="inv-title">Inventory Overview</h1>
 <p className="inv-subtitle">
 Current inventory position across materials, locations, batches,
 and inventory categories.
 </p>
 </header>

 <SummaryCards
 summary={
 data?.summary || {
 totalRecords: 0,
 totalQuantity: 0,
 totalReserved: 0,
 totalAvailable: 0,
 }
 }
 />

 <CategoryGrid categories={data?.categories || []} />

 <StockFilters
 filterOptions={
